'use strict';
(function(){
let step=0,frame=0,tutorialFrame=0,launchAfterTutorial=false;
// These images are screenshots of the matching tutorial game screens, captured in the browser.
const USE_SCREENSHOTS=true;
const titles=['How will you fight?','Pick your targets.','Turn up the pressure.','Ready to make a mark?'];
const nextLabels=['Choose targets →','Choose your pace →','Review your run →'];
function showScreen(container,c,i){if(!USE_SCREENSHOTS){InkGuideRender.renderExample(container,c,i);return}container.replaceChildren();container.className='guide-screen screenshot-screen';const img=document.createElement('img');img.src=`assets/guides/${c.control}-${c.skill}-${i}.jpg`;img.alt=`Example screen ${i+1}: ${InkOnboarding.guidePages(c)[i].title}`;img.width=440;img.height=330;img.onerror=()=>InkGuideRender.renderExample(container,c,i);container.append(img)}
function refresh(reset=false){const c=currentSetup();if(reset)frame=0;const pages=InkOnboarding.guidePages(c),page=pages[frame];$('guideMode').textContent=`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()}`;$('guideHero').innerHTML=c.control==='voice'?'YOUR VOICE.<br><em>THEIR PROBLEM.</em>':'QUICK KEYS.<br><em>QUICK SPELLS.</em>';$('guideIntro').textContent=c.control==='voice'?'See the target. Say it clearly. Watch it fall.':'Read the target. Type the answer. Keep moving.';showScreen($('guideScreen'),c,frame);$('guideFrameNumber').textContent=`0${frame+1} / 03`;$('guideFrameTitle').textContent=page.title;$('guideFrameText').textContent=page.text;$('guidePrev').disabled=frame===0;$('guideNext').disabled=frame===2;$('guideDots').replaceChildren(...pages.map((_,i)=>{const b=document.createElement('button');b.type='button';b.textContent=String(i+1);b.setAttribute('aria-label',`Example screen ${i+1}`);b.setAttribute('aria-current',i===frame?'step':'false');b.onclick=()=>{frame=i;refresh()};return b}));const pace=paceFor(c.speed,c.control);document.querySelectorAll('[name=speed]').forEach(r=>{const p=paceFor(r.value,c.control);r.parentElement.querySelector('i').textContent=`${p.travel} sec travel${c.control==='voice'?` · Max ${p.cap}`:''}`});$('speedNote').textContent=`${pace.name}: monsters arrive about every ${pace.spawn} seconds and take ${pace.travel} seconds to travel the arena. ${c.control==='voice'?`At most ${pace.cap} monsters, with a 1.4 sec grace at the line. Waves increase more gently.`:'Every 20-second wave gets faster.'}`;const summary=$('runSummary');summary.replaceChildren();for(const[label,value]of[['Controls',{type:'Type to fire',voice:'Speak aloud'}[c.control]],['Targets',skillNames[c.skill]+(['numbers','mixed'].includes(c.skill)?` · 0–${c.range}`:'')],['Pace',pace.name],['Length',c.duration?`${c.duration/60} minutes`:'Endless']]){const row=document.createElement('div'),dt=document.createElement('span'),dd=document.createElement('strong');dt.textContent=label;dd.textContent=value;row.append(dt,dd);summary.append(row)}$('keyboardReminder').hidden=c.control!=='type';const first=InkOnboarding.needsTutorial(c,readLocal);$('firstRunNote').textContent=first?'First time with this mode? Three quick instruction screens come before the match.':'You’ve learned this mode. Start straight away, or replay the instructions.';$('musicNote').textContent=c.control==='voice'?'Music and effects play very softly while the microphone listens. Headphones help keep speech clear.':'One adaptive soundtrack follows the actual monster speed. Music and effects are adjustable from Audio.';}
function setStep(n,scroll=true){stopMicCheck();gameAudio.stop();step=Math.max(0,Math.min(3,n));document.querySelectorAll('[data-step]').forEach(el=>el.hidden=+el.dataset.step!==step);$('wizardTitle').textContent=titles[step];$('wizardEyebrow').textContent=`STEP ${step+1} OF 4`;$('wizardProgress').querySelectorAll('li').forEach((li,i)=>{li.className=i===step?'current':i<step?'complete':'';li.setAttribute('aria-current',i===step?'step':'false')});$('wizardBack').hidden=step===0;$('wizardNext').hidden=step===3;$('startBtn').hidden=step!==3;$('wizardNext').textContent=nextLabels[step]||'Continue →';$('setupStatus').textContent=step===0?'Choose one control. You can change it before every run.':step===1?`Choose the skill and difficulty. See an example ${window.innerWidth<760?'below':'on the left'}.`:step===2?'Speaking automatically gets fewer, slower targets. Choose the pressure that suits you.':'Five hearts. Automatic spells. You’re ready.';refresh();if(scroll&&window.innerWidth<760)$('wizardEyebrow').scrollIntoView({behavior:'smooth',block:'start'});}
function renderTutorial(){const c=currentSetup(),pages=InkOnboarding.guidePages(c),p=pages[tutorialFrame];showScreen($('tutorialScreen'),c,tutorialFrame);$('tutorialMode').textContent=`${skillNames[c.skill].toUpperCase()} / ${c.control.toUpperCase()} · QUICK GUIDE`;$('tutorialCount').textContent=`0${tutorialFrame+1} / 03`;$('tutorialTitle').textContent=p.title;$('tutorialText').textContent=p.text;$('tutorialBack').disabled=tutorialFrame===0;$('tutorialNext').textContent=tutorialFrame===2?(launchAfterTutorial?'Got it. Start the run ↗':'Got it. Back to setup →'):'Next →';}
function openTutorial(launch){stopMicCheck();gameAudio.stop();launchAfterTutorial=launch;tutorialFrame=0;renderTutorial();$('tutorialDialog').showModal();}
function requestStart(){gameAudio.prepare();gameAudio.stop();if(InkOnboarding.needsTutorial(currentSetup(),readLocal))openTutorial(true);else startRun();}
$('setupForm').addEventListener('change',()=>{gameAudio.stop();refresh(true)});$('setupForm').onsubmit=e=>{e.preventDefault();if(step<3)setStep(step+1);else requestStart()};$('wizardNext').onclick=()=>setStep(step+1);$('wizardBack').onclick=()=>setStep(step-1);$('guidePrev').onclick=()=>{frame=Math.max(0,frame-1);refresh()};$('guideNext').onclick=()=>{frame=Math.min(2,frame+1);refresh()};$('replayTutorial').onclick=()=>openTutorial(false);$('tutorialBack').onclick=()=>{tutorialFrame=Math.max(0,tutorialFrame-1);renderTutorial()};$('tutorialNext').onclick=()=>{if(tutorialFrame<2){tutorialFrame++;renderTutorial();return}saveLocal(InkOnboarding.tutorialKey(currentSetup()),true);$('tutorialDialog').close();refresh();if(launchAfterTutorial)startRun()};$('tutorialClose').onclick=()=>$('tutorialDialog').close();
window.InkGuide={refresh,setStep,requestStart};setStep(0,false);
})();
